// @name Colors
// @background #18181b
// @refresh 3600
// Tailwind's palette, picked by tapping. The classes are read when the frame
// draws, so `bg-${hue}-${shade}` works for every hue and shade.
const hues = ['red', 'orange', 'amber', 'yellow', 'lime', 'green', 'emerald', 'teal', 'cyan',
  'sky', 'blue', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose', 'stone']
const shades = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950]

let hue = 'sky'
let shade = 500

// The picked color outlives the render: a board may start each render with a
// fresh module, and a frame rendered on its server does, at every tap.
const recallPick = () => {
  const kept = frameos.recall('pick')
  if (kept) {
    hue = kept.hue
    shade = kept.shade
  }
}
const pick = (next) => {
  if (next.hue) hue = next.hue
  if (next.shade) shade = next.shade
  frameos.remember('pick', { hue, shade })
}

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// The swatches keep their colors in high contrast: their outlines, the
// picked one's mark and the label go black and white.
const THEMES = {
  color: {
    page: 'bg-zinc-900 text-white',
    card: 'p-5',
    hint: 'opacity-70',
    chip: '',
    swatch: '',
    picked: 'border-4 border-white',
    press: 'active:border-4 active:border-white/50',
    mark: false,
  },
  high: {
    page: 'bg-white text-black',
    card: 'p-[18px] border-2 border-black',
    hint: '',
    chip: 'self-start flex flex-col px-3 py-1 rounded-xl bg-white text-black border-2 border-black',
    swatch: 'border-2 border-black',
    picked: 'flex items-center justify-center border-4 border-black',
    press: '',
    mark: true,
  },
}

// The picked swatch's mark in high contrast: a white dot ringed in black,
// seen on any shade.
const Mark = () => <div className="w-4 h-4 rounded-full bg-white border-2 border-black" />

export function get(app) {
  recallPick()
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const ink = shade < 400 ? 'text-black/80' : 'text-white'
  const label = [
    <span className={`text-sm uppercase font-semibold ${t.hint}`}>Tap a color</span>,
    <span className="text-3xl font-mono">{`bg-${hue}-${shade}`}</span>,
  ]
  return (
    <div className={`flex flex-col gap-3 p-5 ${t.page}`}>
      <div className={`flex flex-col justify-end h-36 rounded-3xl ${t.card} bg-${hue}-${shade} ${t.chip ? '' : ink}`}>
        {t.chip ? <div className={t.chip}>{label}</div> : label}
      </div>
      <div className="flex gap-1 h-12">
        {shades.map((s) => (
          <div className={`flex-1 rounded-lg bg-${hue}-${s} ${s === shade ? t.picked : t.swatch}`}
            onClick={() => pick({ shade: s })}>
            {t.mark && s === shade ? <Mark /> : null}
          </div>
        ))}
      </div>
      <div className="flex-1 grid grid-cols-6 gap-2">
        {hues.map((h) => (
          <div className={`rounded-xl bg-${h}-500 ${h === hue ? t.picked : `${t.swatch} ${t.press}`}`}
            onClick={() => pick({ hue: h })}>
            {t.mark && h === hue ? <Mark /> : null}
          </div>
        ))}
      </div>
    </div>
  )
}
